  "content": "import { formatTable } from '../../format-table.js';
import { defineCommand } from '../../lib/define-command.js';
import { styleText } from '../../lib/style-text.js';
import { Logger } from '../../logger.js';
import * as Application from '../../models/application.js';
import { listInstances } from '../../models/instances.js';
import { aliasOption, appIdOrNameOption, humanJsonOutputFormatOption } from '../global.options.js';

export const instancesCommand = defineCommand({
  description: 'List the instances of an application',
  since: null,
  options: {
    alias: aliasOption,
    app: appIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [],
  async handler(options) {
    const { alias, app: appIdOrName, format } = options;
    const { ownerId, appId } = await Application.resolveId(appIdOrName, alias);

    const instances = await listInstances({ ownerId, appId, onlyRunning: true });

    switch (format) {
      case 'json': {
        Logger.printJson(instances);
        break;
      }
      case 'human':
      default: {
        if (instances.length === 0) {
          Logger.println('🔎 No running instance found');
          return;
        }
        const header = ['Instance', 'Name', 'State', 'Flavor', 'Type', 'Deployment', 'Created at'].map((title) =>
          styleText('bold', title),
        );
        const rows = instances.map((instance) => [
          instance.id,
          instance.name ?? '',
          instance.state,
          instance.flavor ?? '',
          instance.isBuildVm ? 'build' : 'run',
          instance.deploymentId,
          instance.createdAt,
        ]);
        Logger.println(formatTable([header, ...rows]));
      }
    }
  },
});
